/**
 * @suppress
 */
public object FfiConverterTypeEpochKeyManager: FfiConverter<EpochKeyManager, Pointer> {

    override fun lower(value: EpochKeyManager): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): EpochKeyManager {
        return EpochKeyManager(value)
    }

    override fun read(buf: ByteBuffer): EpochKeyManager {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: EpochKeyManager) = 8UL

    override fun write(value: EpochKeyManager, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



