    }

    override fun allocationSize(value: ParsedEnvelope) = (
            FfiConverterUByte.allocationSize(value.`version`) +
            FfiConverterTypeSealMode.allocationSize(value.`mode`) +
            FfiConverterBoolean.allocationSize(value.`anonymous`) +
            FfiConverterByteArray.allocationSize(value.`salt`) +
            FfiConverterSequenceTypeEnvelopeEntry.allocationSize(value.`entries`) +
            FfiConverterByteArray.allocationSize(value.`nonce`) +
            FfiConverterByteArray.allocationSize(value.`ciphertext`) +
            FfiConverterByteArray.allocationSize(value.`header`)
    )

    override fun write(value: ParsedEnvelope, buf: ByteBuffer) {
            FfiConverterUByte.write(value.`version`, buf)
            FfiConverterTypeSealMode.write(value.`mode`, buf)
            FfiConverterBoolean.write(value.`anonymous`, buf)
            FfiConverterByteArray.write(value.`salt`, buf)
            FfiConverterSequenceTypeEnvelopeEntry.write(value.`entries`, buf)
            FfiConverterByteArray.write(value.`nonce`, buf)
            FfiConverterByteArray.write(value.`ciphertext`, buf)
            FfiConverterByteArray.write(value.`header`, buf)
    }
}



