/**
 * Every failure carries the stable code shared by all QoreSeal
 * implementations (for example `NOT_A_RECIPIENT`) and a human-readable
 * detail. (The field is not named `message`: that clashes with
 * `Throwable.message` in the Kotlin bindings.)
 */
sealed class QoreSealException: kotlin.Exception() {
    
    class Failure(
        
        val `code`: kotlin.String, 
        
        val `detail`: kotlin.String
        ) : QoreSealException() {
        override val message
            get() = "code=${ `code` }, detail=${ `detail` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<QoreSealException> {
        override fun lift(error_buf: RustBuffer.ByValue): QoreSealException = FfiConverterTypeQoreSealError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeQoreSealError : FfiConverterRustBuffer<QoreSealException> {
    override fun read(buf: ByteBuffer): QoreSealException {
        

        return when(buf.getInt()) {
            1 -> QoreSealException.Failure(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: QoreSealException): ULong {
        return when(value) {
            is QoreSealException.Failure -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`code`)
                + FfiConverterString.allocationSize(value.`detail`)
            )
        }
    }

    override fun write(value: QoreSealException, buf: ByteBuffer) {
        when(value) {
            is QoreSealException.Failure -> {
                buf.putInt(1)
                FfiConverterString.write(value.`code`, buf)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * `Hybrid` (default): ML-KEM-1024 plus X25519. `Mlkem`: ML-KEM-1024 only.
