public object FfiConverterTypeSealMode: FfiConverterRustBuffer<SealMode> {
    override fun read(buf: ByteBuffer) = try {
        SealMode.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: SealMode) = 4UL

    override fun write(value: SealMode, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}






